const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');
const path = require('path');

async function main() {
  const scalekit = new Scalekit(
    process.env.SCALEKIT_ENVIRONMENT_URL,
    process.env.SCALEKIT_CLIENT_ID,
    process.env.SCALEKIT_CLIENT_SECRET
  );

  try {
    const organizationId = 'org_1234567890';
    const result = await scalekit.organization.generatePortalLink(organizationId, {
      features: ['sso', 'directory_sync']
    });

    const portalLink = result.link;
    const outputPath = '/home/user/scalekit-admin/portal_link.txt';

    fs.writeFileSync(outputPath, portalLink);
    console.log(`Portal link generated and written to ${outputPath}`);
  } catch (error) {
    console.error('Error generating portal link:', error);
    process.exit(1);
  }
}

main();

